CREATE TABLE el_organization_profiles(org_id TEXT PRIMARY KEY REFERENCES el_organizations(id),display_name TEXT NOT NULL DEFAULT '',tagline TEXT NOT NULL DEFAULT '',contact_email TEXT NOT NULL DEFAULT '',contact_phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',website TEXT NOT NULL DEFAULT '',default_language TEXT NOT NULL DEFAULT 'en' CHECK(default_language IN ('en','ar')),financial_year_start_month INTEGER NOT NULL DEFAULT 1 CHECK(financial_year_start_month BETWEEN 1 AND 12),updated_at INTEGER NOT NULL);
